{
	"$schema": "./node_modules/nx/schemas/nx-schema.json",
	"namedInputs": {
		"default": ["{projectRoot}/**/*", "sharedGlobals"],
		"production": [
			"default",
			"!{projectRoot}/**/*.test.ts",
			"!{projectRoot}/**/*.spec.ts",
			"!{projectRoot}/**/*_test.go",
			"!{projectRoot}/tests/**/*"
		],
		"sharedGlobals": ["{workspaceRoot}/.env"]
	},
	"targetDefaults": {
		"build": {
			"cache": true,
			"dependsOn": ["^build"],
			"inputs": ["production", "^production"]
		},
		"tsc": {
			"cache": true,
			"inputs": ["default", "^production"]
		},
		"test": {
			"cache": true,
			"inputs": ["default", "^production"]
		},
		"lint": {
			"cache": true
		}
	},
	"parallel": 3,
	"nxCloudAccessToken": null,
	"analytics": false
}

